package io.github.manoelcampos.java2ts.javadoc;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class CommentCleanerTest {
    @Test
    void cleansComments() {
        assertEquals("See {@link Foo}.\nUse `x < y` and `a`.\nReturns the name", CommentCleaner.clean("  See ,{@link Foo},.\n  Use {@code x < y} and {@literal a}.\n {@return the name}"));
        assertEquals("", CommentCleaner.clean(null));
    }

    /**
     * Uses the text generated by the xml-doclet for the comment in the issue #5,
     * which has commas around inline tags, except when they are next to an HTML element.
     */
    @Test
    void keepsLinkAtTheStartOfListItems() {
        assertEquals("<li>{@link ImportJob} (text after the link).</li>", CommentCleaner.clean("<li>{@link ImportJob}, (text after the link).</li>"));
        assertEquals("<li>{@link ImportJob}, text with a comma after the link.</li>", CommentCleaner.clean("<li>{@link ImportJob},, text with a comma after the link.</li>"));
        assertEquals("<li>end {@link ImportJob}</li>", CommentCleaner.clean("<li>end ,{@link ImportJob}</li>"));
    }

    @Test
    void keepsLinkInTheMiddleOfSentences() {
        assertEquals("<li>Link in the middle: the {@link ImportJob} (in parentheses).</li>", CommentCleaner.clean("<li>Link in the middle: the ,{@link ImportJob}, (in parentheses).</li>"));
        assertEquals("Outside a list: {@link ImportJob} (in parentheses).", CommentCleaner.clean("Outside a list: ,{@link ImportJob}, (in parentheses)."));
        assertEquals("Mid {@link A}, comma.", CommentCleaner.clean("Mid ,{@link A},, comma."));
    }

    @Test
    void keepsCommasBetweenAdjacentTags() {
        assertEquals("Two {@link A} {@link B}.", CommentCleaner.clean("Two ,{@link A}, ,{@link B},."));
        assertEquals("{@link A}`x`", CommentCleaner.clean("{@link A},{@code x}"));
        assertEquals("{@link A},`x`", CommentCleaner.clean("{@link A},,,{@code x}"));
    }

    @Test
    void keepsBalancedBracesInsideCode() {
        assertEquals("Code with braces: `POST /import-jobs/{id}/retry`.", CommentCleaner.clean("Code with braces: ,{@code POST /import-jobs/{id}/retry},."));
        assertEquals("`a{b{c}}d` and `{x}`", CommentCleaner.clean("{@code a{b{c}}d}, and ,{@code {x}}"));
        assertEquals("Code without braces: `POST /import-jobs`.", CommentCleaner.clean("Code without braces: ,{@code POST /import-jobs},."));
    }

    @Test
    void replacesTagsInsideReturn() {
        assertEquals("Returns the `x` value of {@link A}", CommentCleaner.clean("{@return the {@code x} value of {@link A}}"));
    }

    @Test
    void keepsUnclosedTags() {
        assertEquals("Unclosed {@code x", CommentCleaner.clean("Unclosed {@code x"));
    }

    @Test
    void removesTagNameFromTagText() {
        assertEquals("Manoel", CommentCleaner.tagText("author", "@author Manoel"));
        assertEquals("Manoel", CommentCleaner.tagText("author", "Manoel"));
    }
}
